<?php
namespace App\Http\Controllers;
use App\Enums\RoleCode;use App\Models\Project;use App\Models\RoleAssignment;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class UserController extends Controller {
 public function index(){return view('users.index',['users'=>User::with('activeAssignment.project')->latest()->get(),'projects'=>Project::active()->orderBy('name')->get(),'roles'=>RoleCode::cases()]);}
 public function store(Request $r){$roles=array_map(fn(RoleCode $role)=>$role->value,RoleCode::cases());$d=$r->validate(['name'=>'required|string|max:255','mobile'=>['required','regex:/^09\d{9}$/','unique:users,mobile'],'role_code'=>['required',Rule::in($roles)],'project_id'=>'nullable|exists:projects,id']);$projectRole=in_array($d['role_code'],['project_operator','project_manager'],true);if($projectRole&&!$d['project_id'])return back()->withErrors(['project_id'=>'انتخاب پروژه برای این نقش الزامی است.'])->withInput();if(!$projectRole)$d['project_id']=null;if($d['role_code']==='project_manager'&&RoleAssignment::where('role_code','project_manager')->where('project_id',$d['project_id'])->whereNull('ended_at')->exists())return back()->withErrors(['role_code'=>'این پروژه در حال حاضر مدیر فعال دارد.'])->withInput();if(in_array($d['role_code'],['hr_manager','ceo','finance_manager'],true)&&RoleAssignment::where('role_code',$d['role_code'])->whereNull('ended_at')->exists())return back()->withErrors(['role_code'=>'برای این سطح مدیریتی قبلاً کاربر فعال تعیین شده است.'])->withInput();DB::transaction(function()use($d,$r){$u=User::create(['name'=>$d['name'],'mobile'=>$d['mobile'],'is_active'=>true]);RoleAssignment::create(['user_id'=>$u->id,'role_code'=>$d['role_code'],'project_id'=>$d['project_id'],'started_at'=>now(),'assigned_by'=>$r->user()->id]);});return back()->with('status','کاربر ایجاد شد.');}
}
